how.pseudocode:
insert(root, val):
  if root 为空: 返回新节点
  if val < root.val: root.left = insert(root.left, val)
  else if val > root.val: root.right = insert(root.right, val)
  else: 已存在，直接返回
  更新 root.size，返回 root

delete(root, val):
  if root 为空: 返回 None
  if val < root.val: root.left = delete(root.left, val)
  elif val > root.val: root.right = delete(root.right, val)
  else:
    若左/右子树为空 → 返回另一侧
    否则找左子树最大节点(前驱)代替之，删前驱
  更新 root.size，返回 root

search/rank/kth 沿左右分支递归即可

how.python:
class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None
        self.size = 1

class BST:
    def __init__(self):
        self.root = None

    @staticmethod
    def _sz(n):
        return n.size if n else 0

    def _pull(self, n):
        n.size = 1 + self._sz(n.left) + self._sz(n.right)

    def insert(self, val):
        self.root = self._insert(self.root, val)

    def _insert(self, n, val):
        if n is None:
            return Node(val)
        if val < n.val:
            n.left = self._insert(n.left, val)
        else:
            n.right = self._insert(n.right, val)
        self._pull(n)
        return n

    def search(self, val):
        n = self.root
        while n and n.val != val:
            n = n.left if val < n.val else n.right
        return n is not None

    def delete(self, val):
        self.root = self._delete(self.root, val)

    def _delete(self, n, val):
        if n is None:
            return None
        if val < n.val:
            n.left = self._delete(n.left, val)
        elif val > n.val:
            n.right = self._delete(n.right, val)
        else:
            if n.left is None:
                return n.right
            if n.right is None:
                return n.left
            p = n.left
            while p.right:
                p = p.right
            n.val = p.val
            n.left = self._delete(n.left, p.val)
        self._pull(n)
        return n

    def kth(self, k):
        n = self.root
        while n:
            ls = self._sz(n.left)
            if k == ls + 1:
                return n.val
            if k <= ls:
                n = n.left
            else:
                k -= ls + 1
                n = n.right
        raise ValueError("k out of range")

    def inorder(self):
        out = []
        def dfs(n):
            if n is None:
                return
            dfs(n.left)
            out.append(n.val)
            dfs(n.right)
        dfs(self.root)
        return out


def _check_bst_property(n, lo, hi):
    if n is None:
        return True
    if not (lo < n.val < hi):
        return False
    return _check_bst_property(n.left, lo, n.val) and _check_bst_property(n.right, n.val, hi)


if __name__ == "__main__":
    import random
    random.seed(1)
    t = BST()
    for _ in range(200):
        t.insert(random.randint(0, 1000))
    vals = t.inorder()
    assert vals == sorted(vals)
    k = random.randint(1, len(vals))
    assert t.kth(k) == vals[k - 1]
    for v in set(vals):
        while t.search(v):
            t.delete(v)
        assert not t.search(v)
    assert t.inorder() == []
    t = BST()
    for i in range(500):   # 1000 会触发行链递归上限
        t.insert(i)
    assert _check_bst_property(t.root, -1, 500)
    assert t.kth(250) == 249
    print("All tests passed.")
